import { RefactorSuggestion, RefactorConfig } from '../types';

export class RefactorEngine {
  private config: RefactorConfig;

  constructor(config: RefactorConfig) {
    this.config = config;
  }

  async refactorCode(code: string): Promise<RefactorSuggestion[]> {
    const suggestions: RefactorSuggestion[] = [];
    const lines = code.split('\n');
    const rules = this.config.rules || [];

    // 1. Idiom: var -> let/const (Robust Regex for TS/JS)
    if (rules.includes('idiom')) {
      lines.forEach((line, index) => {
        if (/^\s*var\s+/.test(line)) {
          suggestions.push({
            type: 'idiom',
            description: 'Use const/let instead of var for block scoping',
            originalCode: line.trim(),
            suggestedCode: line.trim().replace(/\bvar\b/, 'let'),
            line: index + 1,
            severity: 'medium'
          });
        }
      });
    }

    // 2. Performance: DOM in Loops & N+1 Queries
    if (rules.includes('performance')) {
      let inLoop = false;
      
      lines.forEach((line, index) => {
        if (/\b(for|while|forEach|map)\b/.test(line)) inLoop = true;
        if (inLoop && line.includes('}')) inLoop = false;

        // DOM Thrashing
        if (inLoop && /document\.(querySelector|getElementById|getElementsByClassName)/.test(line)) {
          suggestions.push({
            type: 'performance',
            description: 'Cache DOM queries outside of loops to prevent layout thrashing',
            originalCode: line.trim(),
            suggestedCode: 'const el = document.querySelector(...); // Move outside loop',
            line: index + 1,
            severity: 'high'
          });
        }

        // N+1 Query Detection (Heavy System Killer)
        if (inLoop && /pool\.query|db\.execute|sequelize\.find/.test(line)) {
          suggestions.push({
            type: 'performance',
            description: 'N+1 Query detected: Move database call outside the loop using JOIN or IN clause',
            originalCode: line.trim(),
            suggestedCode: '// Use a single query with WHERE id IN (...)',
            line: index + 1,
            severity: 'critical'
          });
        }
      });
    }

    // 3. Async: Detect .then() chains
    if (rules.includes('async')) {
      if (code.includes('.then(')) {
        suggestions.push({
          type: 'async',
          description: 'Modernize legacy promise chains to async/await syntax',
          originalCode: '.then(function(res) { ... })',
          suggestedCode: 'const res = await fetch(...);',
          line: lines.findIndex(l => l.includes('.then(')) + 1,
          severity: 'high'
        });
      }
    }

    return suggestions;
  }

  async refactorFile(filePath: string): Promise<RefactorSuggestion[]> {
    try {
      const fs = require('fs');
      const code = fs.readFileSync(filePath, 'utf8');
      return this.refactorCode(code);
    } catch (error) {
      return [{ type: 'error', description: 'Could not read file', originalCode: '', suggestedCode: '', line: 0, severity: 'high' }];
    }
  }
}
